4.1. ប្រកាស if
ប្រកាស if ត្រូូវបានប្រើដើម្បីីធ្វើការត្រួួតពិនិត្យលក្ខណ្ឌមួយ។ ប្រសិនបើលក្ខណ្ឌត្រឹឹមត្រូូវ វានឹងអនុវត្តកូដក្នុងរយៈ
ពេល។
#include <stdio.h>
int main() {
    int a = 10;
    if (a > 5) {
        printf("a is greater than 5");
    }
    return 0;
}
ការពន្យល់៖
- កម្មវិធីនេះះពិនិត្យតម្លៃរបស់អថេរ a។
- ប្រសិនបើ a ធំជាង 5, វានឹងបង្ហាញ "a is greater than 5"។
- ប្រសិនបើលក្ខណ្ឌមិនពិត, កូដនៅក្នុង if នឹងមិនត្រូូវបានអនុវត្តទេ។
Output: a is greater than 5
