4.3. ប្រកាស if-elseif-else
ប្រកាស if-elseif-else ត្រូូវបានប្រើដើម្បីីធ្វើការត្រួួតពិនិត្យលក្ខណ្ឌច្រើន។ វាអនុញ្ញាតឱ្យអ្នកពិនិត្យលក្ខណ្ឌ
ជាច្រើនក្នុងលំដាប់។
#include <stdio.h>
int main() {
    int a = 10;
    if (a > 15) {
        printf("a is greater than 15");
    } else if (a > 10) {
        printf("a is greater than 10 but less than or equal to 15");
    } else {
        printf("a is less than or equal to 10");
    }
    return 0;
}

