4.4. ប្រកាស switch
ប្រកាស switch ត្រូូវបានប្រើដើម្បីីធ្វើការត្រួួតពិនិត្យលក្ខណ្ឌច្រើន។ វាអនុញ្ញាតឱ្យអ្នកពិនិត្យតម្លៃរបស់អថេរមួយ
ប្រឆាំំងនឹងតម្លៃជាច្រើន។
#include <stdio.h>
int main() {
    int day = 3;
    switch (day) {
        case 1:
            printf("Monday");
            break;
        case 2:
            printf("Tuesday");
            break;
        case 3:
            printf("Wednesday");
            break;
        default:
            printf("Invalid day");
    }
    return 0;
}
ការពន្យល់៖
- កម្មវិធីនេះះពិនិត្យតម្លៃរបស់អថេរ day។
- ប្រសិនបើ day ស្
មើនឹង 1, វានឹងបង្ហាញ "Monday"។
- ប្រសិនបើ day ស្
មើនឹង 2, វានឹងបង្ហាញ "Tuesday"។
- ប្រសិនបើ day ស្
មើនឹង 3, វានឹងបង្ហាញ "Wednesday"។
- បើមិនដូច្នេះទេ, វានឹងបង្ហាញ "Invalid day"។

