ប្រកាស break ត្រូូវបានប្រើដើម្បីីបញ្ចប់ការអនុវត្តនៃកូដក្នុង switch ឬ loop។
#include <stdio.h>
int main() {
    for (int i = 1; i <= 5; i++) {
        if (i == 3) {
            break; // បញ្ចប់ loop នៅពេល i ស្មើ 3
        }
        printf("%d", i);
    }
    return 0;
}
ការពន្យល់៖
- កម្មវិធីនេះះប្រើ break ដើម្បីីបញ្ចប់ for loop នៅពេល i ស្
មើ 3។
- ដូច្នេះ, វានឹងបង្ហាញតែលេខ 1 និង 2។
Output: 1
2
