4.7. ប្រកាស goto
ប្រកាស goto ត្រូូវបានប្រើដើម្បីីលោតទៅកន្លែងជាក់លាក់នៅក្នុងកូដ។
#include <stdio.h>
int main() {
    int a = 10;
    if (a > 5) {
        goto print_message; // លោតទៅកន្លែង print_message
    }
    printf("This will not be printed");
    print_message:
        printf("a is greater than 5");
    return 0;
}
ការពន្យល់៖
- កម្មវិធីនេះះប្រើ goto ដើម្បីីលោតទៅកន្លែង print_message នៅពេល a ធំជាង 5។
- ដូច្នេះ, វានឹងបង្ហាញ "a is greater than 5"។
Output: a is greater than 5
