#include <stdio.h>
// Recursive function to calculate factorial
int factorial(int n) {
    if (n == 0) {
        return 1; // Base case
    } else {
        return n * factorial(n - 1); // Recursive call
    }
}
int main() {
    int result = factorial(5); // Function call
    printf("Factorial of 5 is: %d\n", result);
    return 0;
}
