14.3. C និងការកម្មវិធីមូលដ្ឋានវត្ថុ-oriented
C មិនមែនជាភាសាកម្មវិធីមូលដ្ឋានវត្ថុទេ ប៉ុន្តែគម្រោងវត្ថុ-oriented ដូចជា encapsulation, inheritance
និង polymorphism អាចត្រូូវបានអនុវត្តន៍តាមរយៈស៊ិិចថួរ (structures), function pointers និង
បច្ចេកទេសផ្សេងៗ។ នេះះអនុញ្ញាតឱ្យអ្នកសម្រួួលទិន្ន័យក្នុងរបៀបៀបដូចកម្មវិធីមូលដ្ឋានវត្ថុ។
#include <stdio.h>
struct Car {
    char model[50];
    int year;
    void (*displayInfo)(struct Car*);  // Function pointer
};
void displayCarInfo(struct Car* car) {
    printf("ម៉ូដែល: %s\nឆ្នាំំ: %d\n", car->model, car->year);
}
int main() {
    struct Car myCar = {"Toyota", 2020, displayCarInfo};
    myCar.displayInfo(&myCar);  // ការហៅវិធី
    return 0;}
Output:
ម៉ូដែល: Toyota
ឆ្នាំំ: 2020
