#include <stdio.h>
#include <stdlib.h>
int main() {
    int* ptr = (int*)malloc(sizeof(int));
    if (ptr == NULL) {
        printf("មេម៉ូរីមិនគ្រ
ប់គ្រា
ន់");
        return 1;
    }
    *ptr = 42;
    printf("តម្លៃក្នុង ptr: %d", *ptr);
    free(ptr);  // បញ្ចប់ការប្រើប្រាា
ស់មេម៉ូរី
