#include <stdio.h>
#include <ctype.h>
int main() {
    char ch = 'A';
    if (isalpha(ch)) {
        printf("%c គឺជាតួអក្សរ", ch);
    }
    printf("%c នៅក្នុងតួអក្សរតូចគឺ: %c", ch, tolower(ch));
    return 0;
}
Output: 
